begin;
create extension if not exists pgtap with schema extensions;
select plan(18);
select has_table('public','audit_events','audit table exists');
select ok(not has_table_privilege('anon','public.audit_events','SELECT'),'anon denied');
select ok(not has_table_privilege('authenticated','public.audit_events','INSERT'),'browser insert denied');
select ok(not has_table_privilege('service_role','public.audit_events','UPDATE'),'service update denied');
select ok(not has_table_privilege('service_role','public.audit_events','DELETE'),'service delete denied');
set local role service_role;
select lives_ok($$insert into public.audit_events(organization_id,actor_kind,action,entity_type,entity_id,reason,correlation_id,idempotency_key) values ('a0000000-0000-0000-0000-000000000001','system','order.created','order','c0000000-0000-4000-8000-000000000001','workflow.started','d0000000-0000-4000-8000-000000000001','e0000000-0000-4000-8000-000000000001')$$,'system append');
select is((select count(*) from public.audit_events where idempotency_key in ('e0000000-0000-4000-8000-000000000001','e0000000-0000-4000-8000-000000000002')),1::bigint,'service reads fixture alongside existing history');
select throws_ok($$insert into public.audit_events(id,organization_id,actor_kind,actor_id,action,entity_type,entity_id,reason,correlation_id,idempotency_key) select gen_random_uuid(),organization_id,actor_kind,actor_id,action,entity_type,entity_id,reason,correlation_id,idempotency_key from public.audit_events$$,'23505','duplicate key value violates unique constraint "audit_events_idempotency_key_key"','duplicate idempotency key with fresh primary key rejected');
select throws_ok($$update public.audit_events set action='order.changed'$$,'42501',null,'actual update denied');
select throws_ok($$delete from public.audit_events$$,'42501',null,'actual delete denied');
reset role;
select throws_ok($$update public.audit_events set action='order.changed'$$,'55000','audit events are append-only','trigger guards privileged overwrite');
select throws_ok($$delete from public.audit_events$$,'55000','audit events are append-only','trigger guards privileged delete');
select throws_ok($$truncate public.audit_events$$,'55000','audit events are append-only','trigger guards truncate');
select throws_ok($$insert into public.audit_events(organization_id,actor_kind,action,entity_type,entity_id,reason,correlation_id,idempotency_key) values ('a0000000-0000-0000-0000-000000000001','staff','order.created','order','c0000000-0000-4000-8000-000000000001','workflow.started','d0000000-0000-4000-8000-000000000001','e0000000-0000-4000-8000-000000000002')$$,'23514',null,'staff requires actor');
set local role authenticated;
select throws_ok($$select * from public.audit_events$$,'42501',null,'browser read denied');
reset role;
savepoint audit_rollback;
insert into public.audit_events(organization_id,actor_kind,action,entity_type,entity_id,reason,correlation_id,idempotency_key) values ('a0000000-0000-0000-0000-000000000001','system','order.created','order','c0000000-0000-4000-8000-000000000001','workflow.started','d0000000-0000-4000-8000-000000000001','e0000000-0000-4000-8000-000000000002');
rollback to audit_rollback;
select is((select count(*) from public.audit_events where idempotency_key in ('e0000000-0000-4000-8000-000000000001','e0000000-0000-4000-8000-000000000002')),1::bigint,'audit participates in transaction rollback');
select ok((select relrowsecurity from pg_class where oid='public.audit_events'::regclass),'RLS enabled');
select throws_ok($$insert into public.audit_events(organization_id,actor_kind,action,entity_type,entity_id,reason,correlation_id,idempotency_key) values ('a0000000-0000-0000-0000-000000000001','system','private chat text','order','c0000000-0000-4000-8000-000000000001','workflow.started','d0000000-0000-4000-8000-000000000001','e0000000-0000-4000-8000-000000000002')$$,'23514',null,'free text rejected at database boundary');
select * from finish();
rollback;
